begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public,extensions;
select plan(37);
insert into auth.users(id,email,raw_user_meta_data) values
 ('30000000-0000-0000-0000-000000000001','m3-sql-admin@example.invalid','{"display_name":"Policy Admin"}'),
 ('30000000-0000-0000-0000-000000000002','m3-sql-user@example.invalid','{"display_name":"Policy Learner"}');
update profiles set role = 'GLOBAL_ADMIN' where id = '30000000-0000-0000-0000-000000000001';
insert into learning_sessions(id,user_id,title) values
 ('31000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','Admin test session'),
 ('31000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000002','Learner test session'),
 ('31000000-0000-0000-0000-000000000003','30000000-0000-0000-0000-000000000002','Another session for the same learner');
insert into private.source_catalog(source_key,provider,canonical_ref,title,category_keys,work_key,author_keys,version_key,version_title,language,retrieved_text)
 values('sql:m3','mock','SQL MOCK:1','Synthetic SQL fixture',array['sql/m3','sql/m3/deeper'],'sql:work',array['sql:author','sql:second-author'],'sql:edition','Synthetic SQL edition','en','SYNTHETIC SQL FIXTURE ONLY');
insert into private.source_catalog(source_key,provider,canonical_ref,title,category_keys,work_key,author_keys,version_key,version_title,language,retrieved_text)
 values('sql:m3-other','mock','SQL MOCK:2','Another synthetic segment',array['sql/m3','sql/m3/deeper'],'sql:work',array['sql:author','sql:second-author'],'sql:edition','Synthetic SQL edition','en','ANOTHER SYNTHETIC SEGMENT');
select throws_ok($q$update private.source_catalog set version_key='changed' where source_key='sql:m3'$q$,'22023','Source snapshots are immutable; register a new source key for changed text or metadata','An existing source key cannot silently change edition');
create temporary table m3_state(rule_id uuid,grant_id uuid,hit_id uuid);
insert into m3_state default values;
grant all on m3_state to authenticated;

select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'reason','NO_MATCHING_RULE','Unmatched sources default to deny');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
select throws_ok($q$select public.manage_source_policy(null,0,'WORK','sql:work','APPROVED','Forbidden')$q$,'42501','Global admin required','Normal user cannot manage global source rules');
select throws_ok($q$insert into public.source_policy_rules(scope_type,scope_key,state,revision,admin_display_name) values('WORK','forged','APPROVED',0,'Fake')$q$,'42501','permission denied for table source_policy_rules','Direct policy writes are denied');
select throws_ok($q$select public.source_gateway_mock_text('30000000-0000-0000-0000-000000000002','sql:m3')$q$,'42501','permission denied for function source_gateway_mock_text','Client cannot bypass gateway to read provider text');
select throws_ok('select retrieved_text from public.source_hits','42501','permission denied for table source_hits','Client cannot read saved text directly');
select throws_like($q$insert into public.source_authorizations(user_id,session_id,source_key,policy_rule_id,policy_revision,expires_at) values('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3',gen_random_uuid(),0,now()+interval '1 hour')$q$,'%permission denied%','User cannot forge an authorization row');

select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select public.manage_source_policy(null,(public.source_policy_configuration()->>'revision')::bigint,'CATEGORY','sql/m3','APPROVED','Test category');
reset role;
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'allowed','true','Approved category passes');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
update m3_state set rule_id = public.manage_source_policy(null,(public.source_policy_configuration()->>'revision')::bigint,'WORK','sql:work','ON_REQUEST','Test work');
reset role;
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'allowed','false','Specific ON_REQUEST work overrides approved category');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
update m3_state set grant_id = public.authorize_source_once('31000000-0000-0000-0000-000000000002','sql:m3');
reset role;
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'allowed','true','Explicit temporary authorization passes');
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000003','sql:m3')->>'allowed','false','Permission cannot be reused in another session of the same learner');
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3-other')->>'allowed','false','Permission cannot be reused for another segment of the same work and edition');
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000001','31000000-0000-0000-0000-000000000001','sql:m3')->>'allowed','false','Permission cannot be reused by another learner/session');
update source_authorizations set expires_at = now()-interval '1 second' where id = (select grant_id from m3_state);
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'allowed','false','Expired permission is rejected');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
update m3_state set grant_id = public.authorize_source_once('31000000-0000-0000-0000-000000000002','sql:m3');
select public.revoke_source_authorization(grant_id) from m3_state;
reset role;
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'allowed','false','Revoked permission is rejected');

set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select public.manage_source_policy(null,(public.source_policy_configuration()->>'revision')::bigint,'AUTHOR','sql:author','EXCLUDED','Global author exclusion');
select public.manage_source_policy(null,(public.source_policy_configuration()->>'revision')::bigint,'VERSION','sql:edition','APPROVED','Narrow approval');
reset role;
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'state','EXCLUDED','Excluded author wins over approved edition');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
select throws_ok($q$select public.authorize_source_once('31000000-0000-0000-0000-000000000002','sql:m3')$q$,'42501','Only an ON_REQUEST source in an open session can receive temporary permission','User cannot authorize an excluded source');
reset role;
update source_policy_rules set active = false,retired_at = now() where scope_key like 'sql%';
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select public.manage_source_policy(null,(public.source_policy_configuration()->>'revision')::bigint,'CATEGORY','sql/m3','APPROVED','Broad category');
select public.manage_source_policy(null,(public.source_policy_configuration()->>'revision')::bigint,'CATEGORY','sql/m3/deeper','ON_REQUEST','Narrow category');
reset role;
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'state','ON_REQUEST','Deeper category is more specific');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select public.manage_source_policy(null,(public.source_policy_configuration()->>'revision')::bigint,'AUTHOR','sql:author','APPROVED','First author');
select public.manage_source_policy(null,(public.source_policy_configuration()->>'revision')::bigint,'AUTHOR','sql:second-author','ON_REQUEST','Second author');
reset role;
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'state','ON_REQUEST','Equal-specificity author conflict chooses ON_REQUEST');
select is((select scope_type from source_policy_rules where id = (public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'rule_id')::uuid),'AUTHOR','Author rules outrank category rules');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select public.manage_source_policy(null,(public.source_policy_configuration()->>'revision')::bigint,'WORK','sql:work','APPROVED','Specific work');
reset role;
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'state','APPROVED','Work rules outrank nonexcluded author rules');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select public.manage_source_policy(null,(public.source_policy_configuration()->>'revision')::bigint,'VERSION','sql:edition','ON_REQUEST','Specific edition');
reset role;
select is(public.source_gateway_decide('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3')->>'state','ON_REQUEST','Version rules outrank work rules');
update source_policy_rules set active = false,retired_at = now() where scope_key like 'sql%';
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
update m3_state set rule_id = public.manage_source_policy(null,(public.source_policy_configuration()->>'revision')::bigint,'WORK','sql:work','APPROVED','Approved test work');
select throws_ok($q$select public.manage_source_policy(null,-1,'WORK','sql:other','APPROVED','Stale')$q$,'PT409','Policy changed. Reload before saving.','Stale admin cannot overwrite policy');
reset role;
update m3_state set hit_id = (public.source_gateway_publish('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3','SYNTHETIC SQL FIXTURE ONLY')->>'id')::uuid;
select is((select policy_rule_id from source_hits where id = (select hit_id from m3_state)),(select rule_id from m3_state),'Accepted hit records its authorizing rule');
select ok((select policy_snapshot ? 'revision' and provenance_metadata->>'synthetic' = 'true' from source_hits where id = (select hit_id from m3_state)),'Hit records policy snapshot and synthetic provenance');
select throws_ok($q$select public.source_gateway_publish('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3','Fabricated quote')$q$,'22023','Provider text does not match the retrieved mock fixture','Fabricated provider text is rejected');
select is(public.source_gateway_open('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002',(select hit_id from m3_state))->>'retrieved_text','SYNTHETIC SQL FIXTURE ONLY','Approved saved text can be reopened');
select throws_ok($q$select public.source_gateway_open('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000003',(select hit_id from m3_state))$q$,'42501','Source record unavailable','Saved evidence cannot borrow permission from another session');
select throws_ok($q$select public.source_gateway_open('30000000-0000-0000-0000-000000000001','31000000-0000-0000-0000-000000000001',(select hit_id from m3_state))$q$,'42501','Source record unavailable','Even global admin cannot read another learners source record');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select public.manage_source_policy(rule_id,(public.source_policy_configuration()->>'revision')::bigint,'WORK','sql:work','EXCLUDED','New exclusion') from m3_state;
reset role;
select is((select active from source_policy_rules where id = (select rule_id from m3_state)),false,'Editing retires rather than mutates the authorizing rule');
select is((select state from source_policy_rules where id = (select rule_id from m3_state)),'APPROVED','Historical authorizing rule keeps its original state');
select throws_ok($q$select public.source_gateway_open('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002',(select hit_id from m3_state))$q$,'PT403','Saved source blocked by current policy or permission','Later exclusion blocks saved text');
select ok(not ((public.source_gateway_history('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002')->0) ? 'retrieved_text'),'Blocked history exposes audit metadata, not text');
select throws_ok($q$select public.source_gateway_publish('30000000-0000-0000-0000-000000000002','31000000-0000-0000-0000-000000000002','sql:m3','SYNTHETIC SQL FIXTURE ONLY')$q$,'PT403','Source blocked by current policy or permission','Publication rechecks a newly excluded source');
select is((select count(*)::integer from source_hits where source_key = 'sql:m3'),1,'Blocked publication persists no new hit');
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000002',true);
select throws_ok($q$select public.authorize_source_once('31000000-0000-0000-0000-000000000001','sql:m3')$q$,'42501','Learning session unavailable','Cannot grant permission in another learners session');
reset role;
set local role anon;
select throws_ok('select public.source_policy_configuration()','42501','permission denied for function source_policy_configuration','Anonymous policy access is denied');
reset role;
select * from finish();
rollback;
